from robot.utils.robottime import timestr_to_secs
from socket import timeout as socket_timeout

from ute_fsmaccess import manager
from ute_fsmaccess.scanner.arp import ArpScanner
from ute_common_util.timeout import Timeout
from ute_common_interface.scope import ScopeController
from ute_common_converter.to_number import to_int
from ute_fsmaccess.exception import NotAllHostsFound, SSHServiceUnavailable, RemoteHostUnreachable


class FsmCommonInterface(ScopeController):

    def __init__(self):
        super(FsmCommonInterface, self).__init__()

    def find_available_hosts(self, *hosts, **kwargs):
        """Returns available hosts.

        :param string hosts:            Host Ip Addresses   (e.g. 192.168.255.2    192.168.200.1)

        |

        :kwargs should be used to specify **Timeout** and **Remote host** credentials:
            * **Timeout** (string)          - Maximum time to wait for host answer.Default is 10s.
            * **remote_host** (string)      - Ip address or domain name of remote host.
            * **remote_ssh_user** (string)  - Username for remote host authentication. Default is 'ute'.
            * **remote_ssh_pass** (string)  - Password for remote host authentication. Default is 'ute'.
            * **remote_ssh_prompt** (string)    - SSH prompt received after logging in remote host. Default is '$ '.

        |

        :return: Available hosts.
        :rtype: list

        """
        timeout = timestr_to_secs(kwargs.get('timeout', 10))
        return self._scanner_builder(kwargs).scan_hosts(timeout=timeout, *hosts)

    def wait_until_host_is_available(self, *hosts, **kwargs):
        """Wait until at least one host answers or timeout occurs.

        :param string hosts:            Host Ip Addresses   (e.g. 192.168.255.2    192.168.200.1)

        |

        :kwargs should be used to specify **Timeout** and **Remote host** credentials:
            * **Timeout** (string)          - Maximum time to wait for first host answer.Default is 30s.
            * **remote_host** (string)      - Ip address or domain name of remote host.
            * **remote_ssh_user** (string)  - Username for remote host authentication. Default is 'ute'.
            * **remote_ssh_pass** (string)  - Password for remote host authentication. Default is 'ute'.
            * **remote_ssh_prompt** (string)    - SSH prompt received after logging in remote host. Default is '$ '.

        |

        :return: First discovered host.
        :rtype: string
        """
        timeout = timestr_to_secs(kwargs.get('timeout', 30))
        return self._scanner_builder(kwargs).wait_for_any_host(timeout=timeout, *hosts)

    def wait_until_host_is_unavailable(self, *hosts, **kwargs):
        """Wait until given hosts become unavailable.

        :param string hosts:            Host Ip Addresses   (e.g. 192.168.255.2    192.168.200.1)

        |

        :kwargs should be used to specify **Timeout** and **Remote host** credentials:
            * **Timeout** (string)          - Maximum time to wait for until hosts are unavailable. Default is 30s.
            * **remote_host** (string)      - Ip address or domain name of remote host.
            * **remote_ssh_user** (string)  - Username for remote host authentication. Default is 'ute'.
            * **remote_ssh_pass** (string)  - Password for remote host authentication. Default is 'ute'.
            * **remote_ssh_prompt** (string)    - SSH prompt received after logging in remote host. Default is '$ '.

        |

        :raise:                         Exception if at least one host is still available.
        """
        timeout = timestr_to_secs(kwargs.get('timeout', 30))
        return self._scanner_builder(kwargs).wait_for_unavailable_host(timeout=timeout, *hosts)

    def wait_for_all_hosts(self, *hosts, **kwargs):
        """Wait until all hosts answer.

        :param string hosts:            Host Ip Addresses   (e.g. 192.168.255.2    192.168.200.1)

        |

        :kwargs should be used to specify **Timeout** and **Remote host** credentials:
            * **Timeout** (string)          - Maximum time to wait for all host answers.Default is 30s.
            * **remote_host** (string)      - Ip address or domain name of remote host.
            * **remote_ssh_user** (string)  - Username for remote host authentication. Default is 'ute'.
            * **remote_ssh_pass** (string)  - Password for remote host authentication. Default is 'ute'.
            * **remote_ssh_prompt** (string)    - SSH prompt received after logging in remote host. Default is '$ '.

        |

        :return: All discovered hosts.
        :rtype: list
        """
        timeout = Timeout(timestr_to_secs(kwargs.get('timeout', 30)))
        while timeout.is_not_reached():
            discovered_hosts = self._scanner_builder(kwargs).scan_hosts(timeout=timeout.time_left(), *hosts)
            if sorted(hosts) == sorted(discovered_hosts):
                return
        raise NotAllHostsFound("At least one host was not found.")

    def wait_for_host_ssh(self, host, username='toor4nsn', password='oZPS0POrRieRtu', port=22, prompt='>',
                          attempts=15, timeout=480, remote_host=None, fallback_prompt=None, service_login=False, **kwargs):
        """ Wait until given host has available ssh service.

        :param string host:            Host IP address.
        :param string username:        Host SSH username.
        :param string password:        Host SSH password.
        :param integer port:           Host SSH port.
        :param string prompt:          Host SSH prompt.
        :param integer attempts:       Number of consecutive successful login attempts performed to determine availability of host SSH Service.
        :param integer timeout:        Maximum time (seconds) for waiting for SSH availability.
        :param string remote_host:     IP address of remote host
        :param string fallback_prompt: Client will attempt to use this if 'prompt' fails. As consequence, timeout duration will double.
                                       The default value of 'None' will not trigger this behavior.
        :param bool service_login:      If set, uses serviceuser login (LTE2647) to acquire root privilege.
                                        Uses default private key (id_rsa) in /home/ute/.ssh/toor4nsn/
                                        Custom private key location can be set by kwargs (see below)

        |

        :kwargs should be used to specify **Remote host** credentials:
            * **remote_ssh_user** (string)  - Username for remote host authentication. Default is 'ute'.
            * **remote_ssh_pass** (string)  - Password for remote host authentication. Default is 'ute'.
            * **remote_ssh_prompt** (string)    - SSH prompt received after logging in remote host. Default is '$ '.
            * **remote_ssh_port** (string)    - Port for remote host. Default is 22.
            * **private_key** (string) - Location (absolute path) of custom private key (id_rsa)

        |

        """
        attempts = to_int(attempts)
        port = to_int(port)
        t = Timeout(to_int(timeout))
        tried = 0
        while t.is_not_reached():
            result = self._run_login_test(host, username, password, port, prompt, remote_host, fallback_prompt, service_login, **kwargs)
            tried = tried + 1 if result else 0
            if tried == attempts:
                return
        raise SSHServiceUnavailable('Failed to reach {} successful login attempts in host {} after {} seconds.'.format(attempts, host, timeout))

    def _scanner_builder(self, kwargs):
        executor = None
        ssh_host = kwargs.get('remote_host')
        if ssh_host:
            ssh_user, ssh_pass, ssh_prompt, ssh_port = self._extract_ssh_credentials(kwargs)
            m = manager.SSHConnectionManager(host=ssh_host, user=ssh_user, password=ssh_pass,
                                             port=ssh_port, timeout=30, prompt=ssh_prompt, remote_host=None)

            executor = m.start()
        return ArpScanner(executor=executor)

    def _extract_ssh_credentials(self, kwargs):
        return (kwargs.get('remote_ssh_user', 'ute'),
                kwargs.get('remote_ssh_pass', 'ute'),
                kwargs.get('remote_ssh_prompt', '$ '),
                kwargs.get('remote_ssh_port', 22))

    def _run_login_test(self, host, username, password, port, prompt, remote_host=None, fallback_prompt=None, service_login=False, **kwargs):
        try:
            manager.logger.disabled = True
            m = manager.SSHConnectionManager(host=host, user=username, password=password, port=port, timeout=10, prompt=prompt,
                                             remote_host=remote_host, fallback_prompt=fallback_prompt, service_login=service_login,
                                             **kwargs)
            m.start(timeout=0.5)
            m.stop()
            manager.logger.disabled = False
            return True
        except socket_timeout:
            raise RemoteHostUnreachable("Remote host {} cannot be reached.".format(remote_host))
        except Exception:
            return False
